@app.cell
def _(
    BATCH_SIZE,
    CACHE_DIR,
    EPOCHS,
    EVAL_EVERY,
    EXPERIMENT,
    FAMILY,
    GRAD_ACCUMULATION,
    MAX_GRAD_NORM,
    MAX_STEPS,
    OUTPUT_ROOT,
    Path,
    RESUME_FROM,
    RUN_NAME,
    SAVE_EVERY,
    SEED,
    auth_info,
    configure_policy_model,
    training_policy,
    data_manifest,
    dev_examples,
    environment,
    fit_offline_sft,
    gc,
    json,
    load_pretrained_probe,
    mo,
    torch,
    train_examples,
    training_guard,
    training_spec,
):
    # 12. TRAIN â€” models/optimizer stay owned by this rerun boundary.
    training_result = {"status": "DISABLED", "reason": training_guard}
    run_dir = Path(OUTPUT_ROOT) / EXPERIMENT / RUN_NAME
    if training_guard is None:
        effective_max_steps = (
            MAX_STEPS
            or (
                (len(train_examples) + BATCH_SIZE * GRAD_ACCUMULATION - 1)
                // (BATCH_SIZE * GRAD_ACCUMULATION)
            )
            * EPOCHS
        )
        if effective_max_steps < 1:
            raise ValueError("Invalid complete-epoch training budget.")
        if data_manifest is None:
            raise ValueError("Prepare data first.")
        if not RESUME_FROM and run_dir.exists() and any(run_dir.iterdir()):
            raise FileExistsError(
                "Choose a new RUN_NAME or RESUME_FROM; refusing artifact overwrite."
            )
        model, provenance = load_pretrained_probe(training_spec, CACHE_DIR, SEED)
        try:
            scope = configure_policy_model(model, training_policy)
            compatibility = {
                "architecture": "bifocalgemma_notebook_sft_v2",
                "family": FAMILY,
                "experiment": EXPERIMENT,
                "sources": provenance,
                "data_fingerprint": data_manifest["fingerprint"],
                "training_policy": training_policy,
                "batch_size": BATCH_SIZE,
                "accumulation": GRAD_ACCUMULATION,
                "clip_norm": MAX_GRAD_NORM,
                "seed": SEED,
                "torch": str(torch.__version__),
                "transformers": environment["transformers"],
            }

            def progress(row):
                message = (
                    f"step {row['step']}/{effective_max_steps} Â· train CE {row['train_loss']:.4f}"
                )
                if "eval" in row:
                    message += f" Â· dev CE {row['eval']['loss']:.4f}"
                if "learning_rates" in row:
                    message += " Â· LR " + ", ".join(
                        f"{name}={lr:.2g}" for name, lr in row["learning_rates"].items()
                    )
                if "peak_allocated_gib" in row:
                    message += f" Â· VRAM {row['peak_allocated_gib']:.2f} GiB"
                print(message)

            # Manifest files are written inside the trainer after the run-directory guard.
            training_result = fit_offline_sft(
                model,
                train_examples,
                dev_examples,
                run_dir,
                compatibility,
                max_steps=effective_max_steps,
                epochs=EPOCHS,
                batch_size=BATCH_SIZE,
                accumulation=GRAD_ACCUMULATION,
                training_policy=training_policy,
                clip_norm=MAX_GRAD_NORM,
                eval_every=EVAL_EVERY,
                save_every=SAVE_EVERY,
                seed=SEED,
                resume_from=RESUME_FROM or None,
                progress=progress,
                data_manifest=data_manifest,
            )
            training_result.update(
                {
                    "experiment": EXPERIMENT,
                    "family": FAMILY,
                    "scope": scope,
                    "provenance": provenance,
                    "environment": environment,
                    "authentication": auth_info,
                    "data_fingerprint": data_manifest["fingerprint"],
                }
            )
            (run_dir / "data_manifest.json").write_text(
                json.dumps(data_manifest, indent=2), encoding="utf-8"
            )
            (run_dir / "training_report.json").write_text(
                json.dumps(training_result, indent=2), encoding="utf-8"
            )
        finally:
            del model
            gc.collect()
            torch.cuda.empty_cache()
    mo.md("## 12 Â· Training\nStatus: **" + training_result["status"] + "**")
    return (
        training_result,
        run_dir,
    )


@app.cell
def _(mo, run_dir, training_result):
    # 13. RESULTS â€” cheap presentation separated from training.
    result_summary = {
        key: training_result.get(key)
        for key in (
            "status",
            "global_step",
            "held_out_eval",
            "peak_allocated_bytes",
            "peak_reserved_bytes",
            "checkpoints",
        )
    }
    mo.vstack(
        [
            mo.md(f"## 13 Â· Summary\nArtifacts: `{run_dir}`"),
            mo.ui.table([result_summary], selection=None),
        ]
    )
    return (result_summary,)


@app.cell
def _(
    EXPERIMENT,
    FAMILY,
    HF_REPO_ID,
    HF_UPLOAD_ENABLED,
    HfApi,
    RUN_NAME,
    auth_info,
    hf_download_token,
    mo,
    run_dir,
    training_result,
):
    # 14. HUB UPLOAD â€” upload run artifacts to Hugging Face Hub under {FAMILY}/{EXPERIMENT}/{RUN_NAME}.
    upload_result = {
        "status": "DISABLED",
        "repo_id": HF_REPO_ID,
        "path_in_repo": f"{FAMILY}/{EXPERIMENT}/{RUN_NAME}",
        "reason": "HF_UPLOAD_ENABLED=False",
    }
    if HF_UPLOAD_ENABLED:
        if not HF_REPO_ID or not str(HF_REPO_ID).strip():
            raise ValueError("HF_REPO_ID tidak boleh kosong bila HF_UPLOAD_ENABLED diaktifkan.")
        if not hf_download_token:
            raise RuntimeError(
                "HF token diperlukan untuk upload ke Hugging Face Hub; isi token write pada cell"
                " token atau set environment HF_TOKEN."
            )
        if auth_info.get("role") == "read":
            raise RuntimeError(
                "HF token hanya memiliki akses read; upload ke Hub membutuhkan token dengan akses"
                " write."
            )
        if training_result.get("status") != "COMPLETED":
            upload_result = {
                "status": "SKIPPED",
                "repo_id": HF_REPO_ID,
                "path_in_repo": f"{FAMILY}/{EXPERIMENT}/{RUN_NAME}",
                "reason": (
                    f"Training status is {training_result.get('status')}; only COMPLETED runs"
                    " are uploaded."
                ),
            }
        elif not run_dir.exists() or not any(run_dir.iterdir()):
            upload_result = {
                "status": "SKIPPED",
                "repo_id": HF_REPO_ID,
                "path_in_repo": f"{FAMILY}/{EXPERIMENT}/{RUN_NAME}",
                "reason": f"Run directory `{run_dir}` is empty or does not exist.",
            }
        else:
            api = HfApi(token=hf_download_token)
            api.create_repo(repo_id=HF_REPO_ID, repo_type="model", exist_ok=True)
            commit_url = api.upload_folder(
                folder_path=str(run_dir),
                repo_id=HF_REPO_ID,
                repo_type="model",
                path_in_repo=f"{FAMILY}/{EXPERIMENT}/{RUN_NAME}",
                commit_message=f"Upload artifacts for {FAMILY}/{EXPERIMENT}/{RUN_NAME}",
            )
            upload_result = {
                "status": "COMPLETED",
                "repo_id": HF_REPO_ID,
                "path_in_repo": f"{FAMILY}/{EXPERIMENT}/{RUN_NAME}",
                "commit_url": str(commit_url),
            }
    mo.vstack(
        [
            mo.md(
                f"## 14 Â· Hugging Face Hub upload\nStatus: **{upload_result['status']}** Â· Repo:"
                f" `{HF_REPO_ID}` Â· Path: `{upload_result['path_in_repo']}`"
            ),
            mo.ui.table([upload_result], selection=None),
        ]
    )
    return (upload_result,)


@app.cell
def _(
    EXPERIMENT,
    FAMILY,
    HF_REPO_ID,
    PAIR_OPTIONS,
    RUN_NAME,
    editing_record,
    experiment_spec,
    prepare_editing_records,
    split_editing_records,
):
    def test_family_policy_matches_selected_pair():
        spec = experiment_spec(EXPERIMENT)
        assert spec.tie_encoder_decoder_words == (FAMILY == "symmetric")
        assert EXPERIMENT in PAIR_OPTIONS[FAMILY]

    def test_repository_export_uses_public_context_and_rejects_eval():
        raw = {
            "record_type": "repository_patch_v1",
            "role": "train",
            "instance_id": "synthetic-export",
            "source": "bifocalgemma/synthetic-repository-fixture",
            "source_revision": "fixture-v1",
            "group": "fixture/repo",
            "commit": "a" * 40,
            "repos": "fixture/repo",
            "instruction": "Fix helper.",
            "context": "### File: helper.py\nreturn 0\n",
            "target_patch": "diff --git a/helper.py b/helper.py\n",
            "snapshot_sha256": "b" * 64,
            "context_selection": {"gold_used": False},
        }
        row = editing_record(raw, source="editpackft")
        assert row["context"] == raw["context"]
        try:
            editing_record({**raw, "role": "eval"}, source="editpackft")
            raise AssertionError("Eval export was admitted to training.")
        except ValueError as error:
            assert str(error) == "evaluation_record_cannot_enter_training"

    def test_editing_input_does_not_contain_target_code():
        row = editing_record(
            {
                "old_file": "a.py",
                "new_file": "a.py",
                "old_contents": "x = 0\n",
                "new_contents": "x = 1\n",
                "instruction": "Fix x",
                "commit": "c1",
            },
            source="editpackft",
        )
        assert row["before"] == "x = 0\n"
        assert "+x = 1" in row["target_patch"]
        assert row["instruction"] == "Fix x"

    def test_commit_groups_do_not_overlap():
        rows = []
        for i in range(6):
            rows.append(
                {
                    "old_file": "a.py",
                    "new_file": "a.py",
                    "old_contents": f"x = {i}\n",
                    "new_contents": f"x = {i + 10}\n",
                    "instruction": "Fix x",
                    "commit": f"c{i}",
                }
            )
        records, _ = prepare_editing_records(rows, source="editpackft")
        train, dev = split_editing_records(records, seed=17)
        assert not ({r["group"] for r in train} & {r["group"] for r in dev})

    def test_hub_upload_configuration():
        assert HF_REPO_ID == "daruokta/bifocalgemma-sft"
        path_in_repo = f"{FAMILY}/{EXPERIMENT}/{RUN_NAME}"
        assert path_in_repo.startswith(f"{FAMILY}/")
        assert FAMILY in {"symmetric", "asymmetric"}

    return


if __name__ == "__main__":
    app.run()
